import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UX decision records (UXD)","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/README.md","filePath":"uxs/decisions/README.md"}'),d={name:"uxs/decisions/README.md"};function n(i,e,r,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="ux-decision-records-uxd" tabindex="-1">UX decision records (UXD) <a class="header-anchor" href="#ux-decision-records-uxd" aria-label="Permalink to &quot;UX decision records (UXD)&quot;">​</a></h1><p>The UX counterpart of ADRs: one record per decision about how Orrery looks, reads or behaves for a visitor. ADRs keep architecture decisions; UXDs keep UX ones. Where they live among the UX documents: <a href="./../UXS-000-orrery-ux-architecture">UXS-000</a>.</p><p><strong>Why they exist.</strong> Orrery&#39;s UX rules sit in many places (IA, the UXS documents, the design system doc, AGENTS.md, TA.md) and a decision&#39;s date and reasoning get written into the rule it changed, or only into the operator&#39;s working notes. From here a spec or rules document states the current rule and links the UXD that set it; the reasoning and the options weighed live in the UXD.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>One decision, one record</strong>, numbered in order: <code>UXD-NNN-&lt;slug&gt;.md</code>.</li><li><strong>Status</strong>: <code>proposed</code> then <code>accepted</code> or <code>rejected</code>; later <code>superseded by UXD-NNN</code>. An accepted record is not rewritten; a change of mind is a new record that supersedes it. A <code>rejected</code> record keeps a proposal that was weighed and dropped, so it is not proposed again by accident.</li><li><strong>The decider is the operator.</strong> A record is <code>accepted</code> only on the operator&#39;s recorded go: the date and where it was given (a message, a line in a working plan, a dated operator note). Where the operator decided the question and a lead agent worked out the fix, the record says which part is which.</li><li><strong>Every accepted record names the rules it changes</strong> (spec, IA, design system, AGENTS.md or TA.md section), and those rules link back to it. A decision is not done until its rules say it. UXS-000 §Next lists the lines still to link.</li><li><strong>Input is traceable</strong>: the feedback points (X1, P3 …), questions (Q1 …) and slices (A1 …) it answers, from the working plan and <a href="./../records/UXR-001-2026-11-11-operator-feedback">UXR-001</a>.</li><li><strong>Every record cites its source</strong>: file and line, or the operator note name and date. No decision, date or reason is written that a source does not show.</li><li><strong>Applied project-wide.</strong> A decision lands in every route, component, doc, test and locale in one pass (<a href="./UXD-011-decisions-apply-project-wide">UXD-011</a>).</li></ul><h2 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># UXD-NNN — &lt;the question, as a short title&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Status**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: proposed | accepted | rejected | superseded by UXD-NNN</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Date**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: YYYY-MM-DD (proposed) · YYYY-MM-DD (decided)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Decider**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: the operator — &lt;where the go was given, with the source line&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Answers**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: feedback point ids, Q-ids, slice id</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Changes**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: &lt;spec / IA / design system / AGENTS.md / TA.md sections that now state the rule&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Context</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What is true today and why it is a question (with evidence and file or line references).</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Options</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> … — for / against.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> …</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Decision</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The option chosen, in one paragraph a reader can apply.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Consequences</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What changes in the app, the specs and the tests; what it costs; what it rules out.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Verification</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">How the rule is checked (the guard), or what is not checked yet.</span></span></code></pre></div><h2 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;Index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UXD</th><th>Decision</th><th>Status</th><th>Date</th></tr></thead><tbody><tr><td><a href="./UXD-001-ui-accent-blue-replaces-teal">UXD-001</a></td><td>The UI accent is blue D <code>#5070ff</code>; it replaces every UI teal, and cyan is out</td><td>accepted, implemented in A3</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-002-type-scale-and-the-11px-floor">UXD-002</a></td><td>Type scale: 11 px floor, labels at 60 %, upright Space Mono leads, italic only for quotes and captions</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-003-home-route-card-titles-upright">UXD-003</a></td><td>Home route-card titles are upright Space Mono; the 4.5 px icon text stays deleted</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-004-one-outputpass-per-composer">UXD-004</a></td><td>One OutputPass per composer; colour textures sRGB, data maps linear</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-005-no-staging-verify-on-prod">UXD-005</a></td><td>No staging: Pages serves only the docs; releases go straight to prod and are verified there</td><td>accepted</td><td>2026-11-10</td></tr><tr><td><a href="./UXD-006-mars-moon-square-brackets-dropped">UXD-006</a></td><td>Mars/Moon square brackets on detailed locations: not aligned, dropped</td><td>rejected</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-007-panorama-opens-facing-the-photo">UXD-007</a></td><td>A site panorama opens facing the real photo, not the generated fill</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-008-star-panel-one-hero-and-in-the-sky-tab">UXD-008</a></td><td>Star panel: one hero, the constellation finder in an &quot;In the sky&quot; tab, a Gallery tab for more</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-009-deep-sky-viewer-fits-one-screen">UXD-009</a></td><td>The deep-sky viewer fits one screen; facts read label above value</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-010-ruler-regimes-each-get-their-own-science-card">UXD-010</a></td><td>Each Explore ruler regime gets its own best science card, no repeats within a ruler</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-011-decisions-apply-project-wide">UXD-011</a></td><td>Decisions apply project-wide, no partial updates; screenshots after each slice</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-012-one-page-shell">UXD-012</a></td><td>One page shell: container, title, lead and section label for every text page</td><td>accepted</td><td>2026-11-11</td></tr><tr><td><a href="./UXD-014-one-chip-and-filter">UXD-014</a></td><td>One chip and one filter for every toggle, filter, choice and HUD action</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-015-flat-chip-row">UXD-015</a></td><td>Layer chips are one flat row on Explore and every world; the INDEX absorbs the A–Z</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-016-compact-nav-and-more-menu">UXD-016</a></td><td>Compact nav controls (32 px fine / 44 px touch), one More menu for High contrast, Share and Debug, one 52 px bar</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-017-one-index-on-every-scale">UXD-017</a></td><td>One INDEX on every /explore scale: all selectable objects, black holes in the scale they belong to</td><td>accepted (its &quot;no camera move&quot; line is superseded by UXD-019; amended 2026-11-13 by C6: solar-system meta line, chips for every row, nation dots on the Worlds; and by C6-F: filter chips folded behind a FILTERS button)</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-018-panel-shell-and-actions">UXD-018</a></td><td>Panel shell: one fixed header (badge line carrying back and × at the badges&#39; 24 px, the name below at full width; Share the action row&#39;s last chip; Overview three values per row), one action row of at most three chips, no hero hover glow</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-019-select-equals-focus">UXD-019</a></td><td>Select = focus: every pick opens the panel, rings the body and takes the camera; a chip off clears its kind, a select turns it on; mission links open in place</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-020-explore-readability-pins-rings-labels">UXD-020</a></td><td>/explore readability: one 12 px label, one 44 px ring (gold anchor, blue hover), one placement pass, a steady label offset, 2 px light-year rings</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-021-explore-hud-scale-bar-picker-pills-references">UXD-021</a></td><td>/explore HUD: one fixed-width scale bar (120 px, the value follows), a picker ladder that stays on screen and a row that clears a docked panel, direction pills for their owner only, an aligned REFERENCES grid in the reader&#39;s language, Reset always in its slot</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-022-science-link-lists">UXD-022</a></td><td>Science links: at most five per panel through one helper, curated per body, ranked per mission class, each ruler regime its own card, the section pair identical in every locale</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-023-star-and-outer-panels-follow-the-planet-pattern">UXD-023</a></td><td>Star, outer-scale and black-hole panels follow the planet pattern: one shared body, one hero or none, GALLERY with two images, IN THE SKY for stars, deep-sky and EHT heroes, black holes open in place</td><td>accepted</td><td>2026-11-12</td></tr><tr><td><a href="./UXD-024-orbit-ruler-one-row-draws-its-regime">UXD-024</a></td><td>Orbit ruler: one line per row, a fold, the hovered or open regime drawn in the scene in the highlight blue, one bottom-left column on the Worlds, photos for the residents, 23 founding missions linked and no country tags</td><td>accepted</td><td>2026-11-13</td></tr><tr><td><a href="./UXD-025-lists-carry-a-round-photo">UXD-025</a></td><td>Lists carry a round 28 px photo of the row&#39;s own thing: one <code>EntityThumb</code>, one resolver over a generated manifest (the blessed hero slot&#39;s 192 px WebP), the row&#39;s identity colour as ring and neutral for teal, the dot when there is no file; built for the regime panel, its founding missions, the solar-system and Worlds INDEXes, the station lists, the belt members, the fleet panel and the entity pages (T1 to T4); the PATHS legend follows; T5 (L46) the neighbourhood and outer-scale INDEXes and the Related lists</td><td>accepted</td><td>2026-11-13</td></tr><tr><td><a href="./UXD-026-iconic-missions-legend-and-milestone-boxes">UXD-026</a></td><td>Iconic missions: the legend is a one-line title with an (i) (the why-one-plane popover), the hovered craft&#39;s tagline a card beside its row (no shift), ICONIC MISSIONS the first chip, 28 px rows; the milestone boxes are screen-sized sprites (<code>n/N · date</code> over the name, 12 px at every zoom, no mission name, one mission box at Today, the shared placement pass)</td><td>accepted</td><td>2026-11-13</td></tr><tr><td><a href="./UXD-027-explore-levels-one-table-glyphs-card-and-hint">UXD-027</a></td><td>Explore levels: one shell table (<code>SCALE_SHELLS</code>) read by the nav dropdown, hub, home grid, picker, card and lens story (D4: the dropdown stays); the level&#39;s glyph in the picker chip and rungs and in the nav rows (own gradient defs per instance); a &quot;what you are looking at&quot; card under the picker row (what the level is, the story, up to five <code>/science</code> links, folded on touch and remembered); one welcome hint on <code>/explore</code> and the four Worlds (shown until the first zoom or drag, not stored); 4 keys in 14 locales</td><td>accepted</td><td>2026-11-13</td></tr><tr><td><a href="./UXD-028-explore-and-worlds-link-both-ways">UXD-028</a></td><td>Explore and the Worlds: an explicit link both ways, no switch on zoom (D5); one table (<code>WORLD_LINKS</code>) read by the &quot;Go to Mars&quot; view chip of the Earth, Mars, Venus and Moon panels (Venus new), the <code>/explore/&lt;id&gt;</code> page and the Worlds&#39; &quot;Back to Explore&quot; chip, the first control of the view row (the touch cluster wraps), which returns to <code>/explore?id=&lt;body&gt;</code> with the panel open and the camera on it (the Moon is <code>earth:moon</code>); 5 keys in 14 locales, <code>panel_action_surface</code> removed</td><td>accepted</td><td>2026-11-13</td></tr><tr><td><a href="./UXD-029-planet-heroes-whole-disc-on-black">UXD-029</a></td><td>Planet heroes: the whole disc on black, planets only (EP2, EP3; B-033); the planet panel&#39;s hero is <code>contain</code> on <code>#000</code> in the 16:9 box, the nine heroes are pictures of the planet itself, Mars slot 04 with a tighter crop waits for the operator&#39;s yes</td><td>accepted</td><td>2026-11-13</td></tr><tr><td><a href="./UXD-030-worlds-selected-orbiter-stays-visible-and-framed">UXD-030</a></td><td>The Worlds: a selected orbiter stays visible (W3); while an orbiter is selected the orbits count as in view (the orbiter, its ring, the other orbiters, the ruler; one pure rule, <code>orbitsInViewNext</code>), the selected orbiter wears the outline pass, the view shifts beside the open panel for every selection in the 3D view (the Explore framing is now <code>createPanelFramer</code>, shared), closing an orbiter&#39;s panel ends the selection, a deep link waits for the markers and then flies</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-031-station-assembly-player-fixed-box">UXD-031</a></td><td>The station assembly player keeps one height across its phases (ISS2; E-decisions 22a, 23a): the chip is two fixed one-line rows (name; launcher · date) with an ellipsis, the whole phase in the title and a live region, the hint one row (two reserved at 480 px and below); <code>/iss</code> and <code>/tiangong</code> share it</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-032-program-page-card-rails-and-compact-hardware">UXD-032</a></td><td>The program page (PG2 to PG6; E-decisions 1a to 4a): a section with no rows draws nothing, one 176 px <code>MiniCard</code> in a <code>CardRail</code> for related programs and surface sites, &quot;Go deeper&quot; drops its <code>program</code> rows, hardware is 56 px cards with a 72×48 mini hero (departs from UXD-025 on this page only), the mission pane keeps one box (meta and name one line, blurb three), Earth surface cards link <code>?object=</code></td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-033-program-roster-links-and-milestones">UXD-033</a></td><td>Program rosters (PG7 to PG9; E-decisions 5a to 9a): a row that names an existing mission, craft or module links to it (<code>linked_id</code>, or <code>link</code> for a craft or module, with the station for a module), hardware lists hold the flown vehicles of the program&#39;s missions (launch sites left out), missions that exist join the rosters of Soviet lunar, Ariane, Space Shuttle and Mariner, and rows that are episodes, phases, decisions or plans carry <code>milestone: true</code> and sit under a Milestones section after Missions</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-034-worlds-orbiter-detail-tab-and-panorama-opening">UXD-034</a></td><td>The Worlds&#39; orbiter panel (WM1, W6; D-decisions 4a to 7a): an orbiter (and the 9 Earth objects with a drawing) has a DETAIL tab, not STORY, with the heading &quot;The spacecraft&quot; (one new key); the five drawings the lander filter hid are shown (17 of 19 orbiters); landers keep STORY and &quot;On the surface&quot;; the hero stays first below the action row (guard test); the audit of the 30 panoramas (new <code>photo_span_deg</code> on the 18 partial ones, Insight&#39;s opening yaw fixed, a running fly-in no longer overwrites the opening view) and the e2e UXD-007 promised</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-035-fleet-view-toggle-and-one-missions-list">UXD-035</a></td><td>The fleet page (FL2, FL3; E-decisions 16a to 21a): GRID and LINE-UP are one view radiogroup on the FILTERS row (the kind group only in LINE-UP, FILTERS disabled not removed, <code>?view=lineup&amp;kind=</code>, old <code>category=launcher&amp;view=lineup</code> links still work, leaving the line-up leaves the category filter alone); one MISSIONS tab for every entry from <code>fleetMissionRows</code> (flights and linked missions, a link and a round photo only where the mission exists, the rest plain text, crew as one line of names, no portraits, no patch, no empty circle; ADR-053 amended), one count shared with the OVERVIEW button, which prints the mission&#39;s name for a single mission; the same list on <code>/fleet/&lt;id&gt;</code>; the six <code>gemini-N</code> ids renamed; E3&#39;s era strip left for the end of the arc</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-036-venus-galleries-use-the-worlds-ladder">UXD-036</a></td><td>Venus galleries (VE1; D-decisions 8a, 9a): <code>getSurfaceSiteGallery</code> is the one gallery ladder of the Moon, Mars and Venus (the three site loaders are one-line calls), so Venera 13, Vega 1 and Vega 2 have a hero and a GALLERY tab, on the heroes already blessed (<code>missions/venera-13/02</code>, <code>vega-1/02</code>, <code>vega-2/03</code>) that the INDEX rows already showed; Moon and Mars galleries frozen and compared before/after for all 55 sites; the photo-first guard no longer exempts Venus; no image, slot, override or data file changed</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-037-orbit-band-palette-no-teal">UXD-037</a></td><td>The orbit bands and the old UI teal (operator &quot;yes on losing old teal&quot;): the lowest band of every world is green <code>#8fd16a</code>, the second (HLO, HMO, KUIPER, Earth MEO) rose <code>#f28bb8</code>; ISS, MRO, MAVEN, Juno and the commercial era take the green, Voyager 2&#39;s path magenta <code>#da47eb</code>, the debug panel and dev routes the highlight blue; <code>accent-colour.spec.ts</code> no longer exempts regime or era colours</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-038-one-length-rule-for-the-long-text-pages">UXD-038</a></td><td>One length rule for the long text pages (CR2, CR3, CO1, CO2, CO3; decisions 24a, 26a, 27a, 28a): every list on <code>/credits</code> and <code>/colophon</code> draws its first 10 rows and a &quot;Show all N&quot; chip (<code>ShowAll</code>, <code>$lib/preview-list</code>), the source and section headers stay open so a contents link lands on its header, the <code>/credits</code> contents list is capped below 768px only; the colophon opens with one line &quot;N original works in K sections&quot; counted from the sections it draws (<code>colophonSections</code>), and the interface-graphics count is the glyph registry&#39;s in both the contents and the heading; the 198 cutaways split into 158 spacecraft and 40 launcher sketches by a <code>kind</code> field in <code>original-work.json</code> (the exploded 76 stay whole); a unit guard that every Moon, Mars and Earth scene image has a credit row, plus a browser audit script</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-039-home-two-column-hero-one-glyph-component-and-type-scale">UXD-039</a></td><td>The home page (H1, H2, H3, H8, D1, D2, D3; decisions 33a to 41a): from 1024 px the hero is two columns (the wordmark, tagline, subhead and CTAs left, the same picture 400 px wide right) so the CTAs and the &quot;What is this?&quot; heading are in the first screen at 1366x768 and 1440x900; one <code>RouteGlyph</code> component and one <code>RouteGlyphDefs</code> draw every route-card icon on the home grid and the section hubs (the 535-line copies are gone), the Lab card is first under LEARN, and the glyphs render as before (two drawings kept for earth, programs, live, essays); the cards heading is &quot;All {count} destinations&quot; with the grid&#39;s count in 14 locales; body text on <code>--size-body</code>, <code>--size-lead</code> and <code>--size-meta</code>; the TV two-panel layout kept, its overflow fixed, a TV emulation spec; the hero file is not touched, no video, L3 kept</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-040-gallery-viewer-fits-hub-strips-keep-text-and-one-page-note">UXD-040</a></td><td>The gallery pages (G2 to G6; decisions 42a to 44a): the deep-sky viewer is a two-row grid whose image takes the height the caption stack leaves, so the facts, the credit line and the &quot;show in the sky&quot; button are inside 1366x768 and 1440x900 (the figure scrolls on a phone and in a short window, the image has a 200 px floor), the button&#39;s dark-teal text is the page background token (4.96:1); G2 to G4 mean <code>/gallery/deep-sky</code>; one <code>.page-note</code> footer in the shell file replaces the four footers of deep-sky, posters, patches and sourcing (framed, 12 px, muted blue); the <code>/gallery</code> posters and insignia strips keep their text (no clamp, none under a thumbnail); first gallery spec</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-041-library-names-its-data-sources-and-lists-every-link">UXD-041</a></td><td>The library (LI2, LI3; decisions 29a to 32a, with 25a): a &quot;Planetary models (NASA JPL)&quot; block (three <code>data-sources.json</code> entries: the approximate Keplerian elements, the planetary physical parameters, the satellite parameters) and a &quot;Moon and Mars surface data&quot; block (LROC NAC traverses, the USGS Apollo 17 traverse, the HiRISE-traced Zhurong route, the two Mars sources) as header asides in the one style, both read from <code>data-sources.json</code> so <code>/credits</code> and <code>/library</code> cannot drift; <code>build-link-provenance.ts</code> reads the /science article links and the essay sources (544 rows, 30 new publishers) so &quot;Every external link Orrery sends you to lives here&quot; is true, with a unit test that fails when one is missing; each source block draws its first 10 entity clusters and a &quot;Show all N&quot; chip (UXD-038&#39;s rule)</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-042-plan-to-fly-handoff-grouped-destinations-and-the-journey-bar">UXD-042</a></td><td>Plan to Fly (PL1 to PL3, FY3; decisions G-1a to G-9a): <code>rocket=&lt;rockets.json id&gt;</code> is written by /plan (also into its own URL) and read by /fly through one pure mapping to the vehicle name and the launcher ref, so a plan flight shows the chosen rocket and the payload &quot;Generic spacecraft · N kg&quot; (N the mass the ascent integrates); START WITH LAUNCH and <code>?launch=1</code> work for plan flights, and no launcher means no launch button (the dead button&#39;s cause, <code>resolveLauncher(undefined, &#39;—&#39;)</code>, fixed); the nine planetary moons fly their host&#39;s arc with the moon named (<code>LoadedMission.targetMoon</code>); the destination <code>select</code> has five <code>optgroup</code>s; one marker row on the play bar for the whole journey (ascent beats, cruise milestones and stages, descent beats where a profile exists): 2 px ticks with hover and focus labels, a click seeks, ticks closer than 10 px collapse with a count</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-043-fly-2d-seen-on-the-dark-destination-drawn-and-hud-grid">UXD-043</a></td><td><code>/fly</code> visuals (FY1, FY4; decisions 10a to 14a): the 2D canvas&#39;s rings are neutral white at 0.45 alpha / 1.25 px and the stars 0.15 to 0.51, the not-yet-flown arcs 0.75 (the approved 0.45 measures 1.8:1, under the 3:1 floor), one const object with a contrast test; the 2D scale fits the destination or trajectory (1.5 AU floor, eased, &quot;1 AU = N px&quot; readout, <code>fly_2d_scale_label</code> in 14 locales); the 2D draws only the active destination (the host plus the named moon for the nine moon destinations; no hard-coded Mars); the nine moon textures load in 3D and the targeted moon is highlighted (<code>#889fe7</code>); every <code>/fly</code> label/value block (the <code>.hud</code> panels, the info card, the CAPCOM rows) is a <code>fit-content(50%) / 1fr</code> grid whose value wraps inside its own column</td><td>accepted</td><td>2026-11-14</td></tr><tr><td><a href="./UXD-044-moon-traverses-take-the-mars-line-style">UXD-044</a></td><td>Moon traverses (WM2, L49; Q8: line style only): every Moon route draws the Mars style, the blue-white-amber ramp by distance driven (the files carry no time), casing, kilometre milestones, landing ring, hover card in km from landing; sol ticks, replay, photo pins and the Journey tab stay Mars-only; no LROC or published track was found for Chang&#39;e 3 (Yutu) and Chandrayaan-3 (Pragyan), so they stay 9-point outlines flagged <code>approximate</code> and labelled &quot;Approximate route&quot; (<code>traverse_approximate_route</code>, <code>traverse_hover_km</code> in 14 locales)</td><td>accepted</td><td>2026-11-15</td></tr><tr><td><a href="./UXD-045-index-row-type-is-a-glyph-with-a-tooltip">UXD-045</a></td><td>INDEX rows: the type is a 14 px glyph with a tooltip (hover, keyboard focus) and hidden text for a screen reader, so the name keeps the row&#39;s width; 14 drawings in <code>index-kind-glyph.ts</code>; stars keep their constellation as text; the solar-system and Local Group rows are unchanged</td><td>accepted</td><td>2026-11-15</td></tr><tr><td><a href="./UXD-046-the-launch-runs-a-seeded-camera-director">UXD-046</a></td><td>The launch runs a seeded camera director by default (opening pool, shot pools, beats, blends, framing, clouds, smoke, limb, night lights, a vertical first rise); the light comes from the Sun at the pad at the real launch time, seeded for Plan flights and date-only missions; the Shuttle keeps its payload in the bay; reduced motion gets cuts only; <code>?cam=classic</code> for one release; <code>?debug=1</code> view on /fly.</td><td></td><td></td></tr><tr><td><a href="./UXD-047-the-launch-draws-the-real-pad-of-its-site-and-era">UXD-047</a></td><td>The launch draws the pad of its launch site and year (G4, L58): 16 low-detail models in five families (Apollo/Shuttle LC-39, Soviet, SpaceX, ULA, service towers) at true height against the rocket, picked per launch-site fleet record and launch year (<code>pad-family.ts</code>, one row per record, tested), moving parts a pure function of the mission time; the generic tower stays for a site with no model; each model listed on /colophon; only the LC-39 and strongback sizes are fetched-verified, the rest approximate</td><td>accepted</td><td>2026-11-15</td></tr><tr><td><a href="./UXD-048-missions-one-agency-palette-era-tiles-with-photos-and-agency-dots">UXD-048</a></td><td>/missions has one palette for its 14 agencies; /missions and /fleet are one page pattern from shared components: nine era tiles with a flagship photo and agency dots (ar mirrored), agency chips with dot, name and count, a toolbar (total, Showing, sort, Grid / List), one fixed-footprint EntityCard and a list view (E3, MI2, MI3, D7).</td><td>Unit test of the palette contrast and colour-blind distance, the era bucketing and the flagship picks; e2e on the strip, the pattern and the card size.</td><td></td></tr><tr><td><a href="./UXD-049-deep-sky-panel-in-the-sky-tab">UXD-049</a></td><td>A deep-sky object&#39;s panel has an IN THE SKY tab (L42, OVERVIEW · IN THE SKY): the constellation figure with the object ringed (direction from RA / Dec in the HYG frame, never the scene x, y, z; Serpens&#39; two parts merged), six computed cells (constellation, position, nearest named star within 15 degrees, best months from the JPL Horizons Sun (up 20 degrees in astronomical darkness for four hours a night, at the reader&#39;s latitude), latitude band from the time zone, viewing band by magnitude: naked eye to 6, binoculars to 9, telescope above, none without a magnitude), the zodiac note and the lines action; 13 keys in 14 locales; the entity pages stay as they are (L60)</td><td>accepted</td><td>2026-11-15</td></tr></tbody></table><p>Open questions (D7, Q3 to Q6) are not records; they are listed in <a href="./../UXS-000-orrery-ux-architecture#open">UXS-000 §Open</a>.</p><h2 id="decisions-made-before-this-series" tabindex="-1">Decisions made before this series <a class="header-anchor" href="#decisions-made-before-this-series" aria-label="Permalink to &quot;Decisions made before this series&quot;">​</a></h2><p>The dated decisions already written into IA, the UXS documents, AGENTS.md, the ADRs and the operator&#39;s notes are extracted, one row each, into <a href="./BACKFILL"><code>BACKFILL.md</code></a>: date, decision, who, and where it is stated. They are history, not re-decided; a backfilled decision becomes a full UXD only when it is revisited.</p>`,12)])])}const g=t(d,[["render",n]]);export{u as __pageData,g as default};
